package fpv.render;
import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import arc.struct.IntMap;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import fpv.construction.*;import java.util.*;
public final class PowerConnectionsNativeTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static class Tex extends Texture{Tex(){super();width=height=64;}}
 static LayerRuntime runtime;static long place(int x,int y,int floor,Block block,boolean platform){var a=runtime.apply(Vars.player,LayerActions.Action.place(x,y,floor,block.name,platform,0,LayerComponent.Mode.FREE));check(a.accepted(),"authorized placement: "+a.reason()+" game="+Vars.state.isGame()+" playerDead="+Vars.player.dead()+" unitDead="+Vars.player.unit().dead()+" added="+Vars.player.unit().isAdded());return a.componentId();}
 static long upper(int x,int y,int floor,Block block){int low=-(block.size-1)/2;for(int yy=0;yy<block.size;yy++)for(int xx=0;xx<block.size;xx++)place(x+low+xx,y+low+yy,floor,Blocks.air,true);return place(x,y,floor,block,false);}
 public static void main(String[] args)throws Exception{
  ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
  var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="chemical-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);

  Vars.state.rules.editor=true;Vars.state.rules.unitCap=100;Vars.player=Player.create();Vars.player.team(Team.sharded);var unit=UnitTypes.alpha.create(Team.sharded);unit.set(28*8,28*8);unit.add();Vars.player.unit(unit);Vars.state.rules.editor=true;Vars.state.rules.instantBuild=true;Vars.state.rules.infiniteResources=true;Core.settings.put(LayerRuntime.FREE_PERMISSION,true);
  var altitude=new fpv.units.UnitAltitudeSystem((x,y)->0);runtime=new LayerRuntime(new fpv.world.World3DAdapter(new fpv.terrain.TerrainElevation(),(x,y)->0,altitude));var renderer=new PowerConnectionRenderer();var ground=new IntMap<Building>();
  try{
   for(float[] target:new float[][]{{10,0,0},{0,10,0},{.00001f,10,.00001f},{-5,-7,3}}){var g=new PowerBeamGeometry.Builder();g.span(0,0,0,target[0],target[1],target[2],.05f,1,.8f,.3f);var v=g.finish();check(g.vertices()==24,"one four-sided tube");double length=Math.sqrt(target[0]*target[0]+target[1]*target[1]+target[2]*target[2]);for(int i=0;i<v.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(v[i+j]),"finite horizontal/vertical/diagonal tube");double projection=(v[i]*target[0]+v[i+1]*target[1]+v[i+2]*target[2])/(length*length);check(Math.abs(projection-v[i+7])<.00001,"actual endpoint anchoring and stable longitudinal phase");double radial=Math.sqrt(Math.pow(v[i]-projection*target[0],2)+Math.pow(v[i+1]-projection*target[1],2)+Math.pow(v[i+2]-projection*target[2],2));check(Math.abs(radial-.05)<.00001,"bounded envelope radius");check(Math.abs(v[i+8]-length)<.00001,"world-space pulse scale");}}
   var empty=new PowerBeamGeometry.Builder();empty.span(1,1,1,1,1,1,.05f,1,1,1);empty.span(0,0,0,Float.NaN,1,1,.05f,1,1,1);check(empty.vertices()==0,"zero and invalid runs discarded");
   Vars.world.tile(20,20).setBlock(Blocks.powerNodeLarge,Team.sharded,0);Vars.world.tile(24,20).setBlock(Blocks.powerNodeLarge,Team.sharded,0);var first=Vars.world.tile(20,20).build;var second=Vars.world.tile(24,20).build;ground.put(first.pos(),first);ground.put(second.pos(),second);first.configureAny(second.pos());
   renderer.sync(ground,runtime);check(renderer.links()==1,"native reciprocal links draw once");var e=renderer.edges().get(0);check(e.y()>0&&e.Y()>0,"modeled terminals, not ground");long cached=renderer.builds();var before=LogisticsModelNativeTest.state(first);for(int i=0;i<100;i++)renderer.sync(ground,runtime);check(cached==renderer.builds()&&Arrays.equals(before,LogisticsModelNativeTest.state(first)),"unchanged topology caches meshes without mutating native links");first.power.status=.7f;renderer.sync(ground,runtime);check(cached==renderer.builds(),"charge does not rebuild link geometry");
   long upper=upper(28,20,5,Blocks.powerNodeLarge),middle=upper(28,24,3,Blocks.powerNodeLarge);long groundId=LayerVerticalTransfers.groundId(20,20);check(runtime.nativeBuildings().connectPower(groundId,upper),"accepted Z0-Z5 diagonal");check(runtime.nativeBuildings().connectPower(upper,middle),"accepted upper-upper diagonal");long distant=upper(28,28,15,Blocks.powerNodeLarge);check(!runtime.nativeBuildings().connectPower(groundId,distant),"invalid XYZ range is rejected by existing authoritative solver");renderer.sync(ground,runtime);check(renderer.links()==3,"native plus authorized XYZ edges, no duplicates");check(renderer.edges().stream().anyMatch(l->Math.max(l.y(),l.Y())>runtime.planeHeight(5)),"actual high-floor terminal height");
   runtime.nativeBuildings().disconnectPower(groundId,upper);renderer.sync(ground,runtime);check(renderer.links()==2,"disconnect removed immediately");long wall=upper(24,20,2,Blocks.plastaniumWall);check(!runtime.nativeBuildings().connectPower(groundId,upper),"real intermediate-floor insulation rejects connection");renderer.sync(ground,runtime);check(renderer.links()==2,"rejected blocked link never appears");check(runtime.apply(Vars.player,LayerActions.Action.remove(wall)).accepted(),"normal removal of obstruction accepted");check(runtime.nativeBuildings().connectPower(groundId,upper),"reconnect accepted after obstruction removal");
   var state=runtime.replication();var restore=LayerRuntime.class.getDeclaredMethod("restore",byte[].class,boolean.class);restore.setAccessible(true);restore.invoke(runtime,state,false);renderer.sync(ground,runtime);check(renderer.links()==3,"existing save/replication roundtrip restores valid endpoint instances");
   first.configureAny(second.pos());renderer.sync(ground,runtime);check(renderer.links()==2,"native unconfigure removed immediately");Vars.world.tile(20,20).setAir();runtime.nativeBuildings().pruneInvalidPowerLinks();renderer.sync(ground,runtime);check(renderer.links()==1,"destroyed native source and stale references cannot leave beams");
   var foreign=runtime.building(middle);foreign.team=Team.crux;renderer.sync(ground,runtime);check(renderer.links()==0,"ownership change does not expose invalid foreign edge");
   runtime.close();var replacement=new LayerRuntime(new fpv.world.World3DAdapter(new fpv.terrain.TerrainElevation(),(x,y)->0,altitude));renderer.sync(new IntMap<>(),replacement);check(renderer.links()==0,"new empty world/session clears old links");replacement.close();
   System.out.println("PowerConnectionsNativeTest: "+checks+" real native/XYZ topology, dedup, height, removal, restore, ownership, finite tube and cache checks PASS; mock GL, physical acceptance separate");
  }finally{renderer.close();runtime.close();altitude.close();pix.dispose();}
 }
}
